// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(90000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await page.getByRole("button", { name: "Next: Payment →" }).click();
    await page.getByRole("button", { name: "Next: Review →" }).click();
    await expect(page.getByText("Sunglasses × 1 — $")).toContainText("Sunglasses × 1 — $19.99");
    await expect(page.getByText("Mountain View, CA")).toContainText("Mountain View, CA 94043");
    await expect(page.getByText("Card: **** **** ****")).toContainText("Card: **** **** **** 0454");

    // Review-step Order Summary must mirror the server-rendered cart totals.
    await expect(page.locator("#checkout-step-3 p").filter({ hasText: "Shipping:" })).toContainText("$8.99");
    await expect(page.locator("#checkout-step-3 p").filter({ hasText: "Total:" })).toContainText("$28.98");
    // Same total still shown in the cart summary column: 19.99 + 8.99 = 28.98.
    await expect(page.getByText("$28.98", { exact: true })).toBeVisible();
});
